using UnscRelay.Core;
internal static class NativeInterfaceTextChecks
{
 public static int Run(){var root=Directory.CreateTempSubdirectory("relay-native-language-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS native interface language: "+label);}try{var labels=new NativeInterfaceText(Path.Combine(AppContext.BaseDirectory,"fixtures"));foreach(var language in new[]{"en","fr","de","es"})Check(labels.Text("Riprova verifica",language)!="Riprova verifica"&&labels.Text("Verifica della richiesta di cancellazione",language)!="Verifica della richiesta di cancellazione","recovery actions and title are translated in "+language);Check(labels.Text("Owner = Local User; keep my text", "en")=="Owner = Local User; keep my text","unknown identity/user text is preserved without translation or network");Check(LocalLanguageChoice.Read(root.FullName)=="it","a new workspace defaults to Italian");LocalLanguageChoice.Save(root.FullName,"en");Check(LocalLanguageChoice.Read(root.FullName)=="en","native startup language persists without opening profile or vault data");File.WriteAllText(Path.Combine(root.FullName,"interface-language.json"),"{broken metadata");Check(LocalLanguageChoice.Read(root.FullName)=="it","corrupt non-secret language metadata falls back without restoring account data");File.Delete(Path.Combine(root.FullName,"interface-language.json"));var target=Path.Combine(root.FullName,"language-target.json");File.WriteAllText(target,"sentinel");File.CreateSymbolicLink(Path.Combine(root.FullName,"interface-language.json"),target);try{LocalLanguageChoice.Save(root.FullName,"en");throw new Exception("Linked preference overwritten");}catch(IOException){Check(File.ReadAllText(target)=="sentinel","language persistence refuses redirected targets");}Console.WriteLine("Native interface language checks: "+count);return 0;}finally{root.Delete(true);}}
}
